const button = document.querySelector("#locate");
const output = document.querySelector("#location");
let watchId;

button.addEventListener("click", () => {
  if (!navigator.geolocation) {
    output.textContent = "Location is not available in this browser.";
    return;
  }
  if (watchId !== undefined) return;
  watchId = navigator.geolocation.watchPosition(
    ({ coords }) => { output.textContent = `${coords.latitude}, ${coords.longitude}`; },
    (error) => { output.textContent = `Location unavailable (${error.code}).`; },
    { maximumAge: 30_000, timeout: 10_000 }
  );
});

function stopWatching() {
  if (watchId === undefined) return;
  navigator.geolocation.clearWatch(watchId);
  watchId = undefined;
}

const copyButton = document.querySelector("#copy-link");
const status = document.querySelector("#copy-status");

copyButton.addEventListener("click", async () => {
  const shareUrl = window.location.href;
  if (!navigator.clipboard?.writeText) {
    status.textContent = "Copy is unavailable; select the address bar URL.";
    return;
  }
  try {
    await navigator.clipboard.writeText(shareUrl);
    status.textContent = "Link copied.";
  } catch {
    status.textContent = "Copy was blocked; copy the link manually.";
  }
});

const card = document.querySelector(".card");
const observer = new ResizeObserver(([entry]) => {
  const inlineSize = entry.contentBoxSize?.[0]?.inlineSize ?? entry.contentRect.width;
  const compact = inlineSize < 360;
  card.classList.toggle("card--compact", compact);
});
observer.observe(card);

// Call when this card/view is removed:
function disposeCard() {
  observer.unobserve(card);
  observer.disconnect();
}

function syncAnimation(video) {
  if (document.hidden) video.pause();
  else video.play().catch(() => controls.classList.add("needs-play")); // show a manual play control
}

document.addEventListener("visibilitychange", () => syncAnimation(video));
syncAnimation(video); // also handle the initial state

function dispose() {
  document.removeEventListener("visibilitychange", onVisibilityChange);
}
function onVisibilityChange() { syncAnimation(video); }

